FP:RegisterTalentBuilds({class="MAGE",summary="Level as Frost (the safest: slows, freezes and Ice Barrier) or Fire (more damage, with Pyroblast openers and Blast Wave). Arcane builds around Arcane Blast and Arcane Power and wants more mana between pulls.",order={"Arcane","Fire","Frost"},source="Polestar, with ForeverDB's talent data",sourceUrl="https://foreverdb.net/class/Mage/talents",checkedOn="WoW: Forever beta 1.60.1.70450",builds={{key="arcane",spec="Arcane",split="32/0/19",link="https://foreverdb.net/class/Mage/talents",talents={[10]="Improved Channeling 1",[11]="Improved Channeling 2",[12]="Improved Channeling 3",[13]="Improved Channeling 4",[14]="Improved Channeling 5",[15]="Arcane Concentration 1",[16]="Arcane Concentration 2",[17]="Arcane Concentration 3",[18]="Arcane Concentration 4",[19]="Arcane Concentration 5",[20]="Arcane Blast 1",[21]="Arcane Impact 1",[22]="Arcane Impact 2",[23]="Arcane Impact 3",[24]="Missile Barrage 1",[25]="Arcane Meditation 1",[26]="Arcane Meditation 2",[27]="Arcane Meditation 3",[28]="Arcane Wrath 1",[29]="Arcane Subtlety 1",[30]="Missile Barrage 2",[31]="Presence of Mind 1",[32]="Arcane Mind 1",[33]="Arcane Mind 2",[34]="Arcane Mind 3",[35]="Arcane Mind 4",[36]="Arcane Mind 5",[37]="Arcane Instability 1",[38]="Arcane Instability 2",[39]="Arcane Instability 3",[40]="Arcane Subtlety 2",[41]="Arcane Power 1",[42]="Improved Frostbolt 1",[43]="Improved Frostbolt 2",[44]="Improved Frostbolt 3",[45]="Improved Frostbolt 4",[46]="Improved Frostbolt 5",[47]="Improved Frost Nova 1",[48]="Improved Frost Nova 2",[49]="Permafrost 1",[50]="Permafrost 2",[51]="Permafrost 3",[52]="Frost Channeling 1",[53]="Frost Channeling 2",[54]="Frost Channeling 3",[55]="Piercing Ice 1",[56]="Piercing Ice 2",[57]="Piercing Ice 3",[58]="Ice Block 1",[59]="Arctic Reach 1",[60]="Ice Lance 1"},notes={[10]="Improved Channeling first: Arcane Missiles, and later Arcane Blast, keep going when a mob hits you.",[15]="Arcane Concentration gives free casts now and then