FP:RegisterTalentBuilds({class="WARRIOR",summary="Level as Arms with a two-hander (Mortal Strike, Sweeping Strikes) or Fury (Enrage, Death Wish, then Flurry and Bloodthirst with two weapons). Protection is slower alone but ready to tank any dungeon on the way.",order={"Arms","Fury","Protection"},source="ForeverDB's leveling builds, adapted to level 30",sourceUrl="https://foreverdb.net/class/Warrior/talents",checkedOn="WoW: Forever beta 1.60.1.70450",builds={{key="arms",spec="Arms",split="31/20/0",link="https://foreverdb.net/class/Warrior/talents?lvl=60&t=62fd33.32305013032015201-1505013005",talents={[10]="Improved Heroic Strike 1",[11]="Improved Heroic Strike 2",[12]="Improved Heroic Strike 3",[13]="Deflection 1",[14]="Deflection 2",[15]="Improved Tactical Mastery 1",[16]="Improved Tactical Mastery 2",[17]="Improved Tactical Mastery 3",[18]="Improved Tactical Mastery 4",[19]="Improved Tactical Mastery 5",[20]="Anger Management 1",[21]="Improved Rend 1",[22]="Improved Rend 2",[23]="Improved Rend 3",[24]="Deep Wounds 1",[25]="Deep Wounds 2",[26]="Deep Wounds 3",[27]="Two-Handed Weapon Specialization 1",[28]="Two-Handed Weapon Specialization 2",[29]="Two-Handed Weapon Specialization 3",[30]="Impale 1",[31]="Impale 2",[32]="Sweeping Strikes 1",[33]="Weaponmaster 1",[34]="Weaponmaster 2",[35]="Weaponmaster 3",[36]="Weaponmaster 4",[37]="Weaponmaster 5",[38]="Improved Slam 1",[39]="Improved Slam 2",[40]="Mortal Strike 1",[41]="Cruelty 1",[42]="Cruelty 2",[43]="Cruelty 3",[44]="Cruelty 4",[45]="Cruelty 5",[46]="Unbridled Wrath 1",[47]="Unbridled Wrath 2",[48]="Unbridled Wrath 3",[49]="Unbridled Wrath 4",[50]="Unbridled Wrath 5",[51]="Piercing Howl 1",[52]="Blood Craze 1",[53]="Blood Craze 2",[54]="Blood Craze 3",[55]="Booming Voice 1",[56]="Enrage 1",[57]="Enrage 2",[58]="Enrage 3",[59]="Enrage 4",[60]="Enrage 5"},notes={[10]="Improved Heroic Strike first: Heroic Strike is your main rage dump, and a cheaper one means more of them.",[15]="Improved Tactical Mastery keeps rage when you swap stances, so Charge, Overpower and Battle Stance openers cost you nothing.",[20]="Anger Management is a steady rage trickle in every fight; on Forever it also slows rage loss between pulls.",[24]="Improved Rend and Deep Wounds turn your crits into bleeds; Deep Wounds also opens Impale.",[32]="Sweeping Strikes makes two-mob pulls quick; Weaponmaster then adds crit, armor penetration or extra attacks for your weapon type.",[38]="Improved Slam stops Slam from resetting your swing: a free hit between big two-hander swings.",[40]="Mortal Strike is the capstone and your hardest-hitting strike for the rest of the climb.",[41]="The last 20 points go to Fury: Cruelty and Unbridled Wrath give more crit and more rage.",[56]="Enrage finishes the plan: a damage boost that is often up while you take hits."}},{key="fury",spec="Fury",split="17/34/0",link="https://foreverdb.net/class/Warrior/talents?lvl=60&t=62fd33.32305013-05150135050010521",talents={[10]="Cruelty 1",[11]="Cruelty 2",[12]="Cruelty 3",[13]="Cruelty 4",[14]="Cruelty 5",[15]="Unbridled Wrath 1",[16]="Unbridled Wrath 2",[17]="Unbridled Wrath 3",[18]="Unbridled Wrath 4",[19]="Unbridled Wrath 5",[20]="Piercing Howl 1",[21]="Blood Craze 1",[22]="Blood Craze 2",[23]="Blood Craze 3",[24]="Lingering Rage 1",[25]="Enrage 1",[26]="Enrage 2",[27]="Enrage 3",[28]="Enrage 4",[29]="Enrage 5",[30]="Death Wish 1",[31]="Dual Wield Specialization 1",[32]="Dual Wield Specialization 2",[33]="Dual Wield Specialization 3",[34]="Dual Wield Specialization 4",[35]="Dual Wield Specialization 5",[36]="Flurry 1",[37]="Flurry 2",[38]="Flurry 3",[39]="Flurry 4",[40]="Flurry 5",[41]="Bloodthirst 1",[42]="Gore Drinker 1",[43]="Gore Drinker 2",[44]="Improved Heroic Strike 1",[45]="Improved Heroic Strike 2",[46]="Improved Heroic Strike 3",[47]="Deflection 1",[48]="Deflection 2",[49]="Improved Tactical Mastery 1",[50]="Improved Tactical Mastery 2",[51]="Improved Tactical Mastery 3",[52]="Improved Tactical Mastery 4",[53]="Improved Tactical Mastery 5",[54]="Anger Management 1",[55]="Improved Rend 1",[56]="Improved Rend 2",[57]="Improved Rend 3",[58]="Deep Wounds 1",[59]="Deep Wounds 2",[60]="Deep Wounds 3"},notes={[10]="Cruelty first: more crit for every build, and the way into the Fury tree.",[15]="Unbridled Wrath means more rage from every swing, which matters most with two fast weapons.",[20]="Piercing Howl stops runners and lets you walk away from a bad pull.",[25]="Enrage raises your physical damage after you are hit, so it is often up while you take hits.",[30]="Death Wish is a big cooldown for elites and a fear breaker; it also opens Flurry.",[31]="Dual Wield Specialization: more off-hand damage and rage now that you carry two weapons.",[41]="Bloodthirst is the capstone: a strong instant attack and a little run speed between mobs.",[42]="Gore Drinker turns your rage cooldowns into self-healing, so you rest less.",[44]="Spare points go to Arms for cheaper Heroic Strikes, stance-swap rage, Anger Management and Deep Wounds."}},{key="protection",spec="Protection",split="10/0/41",link="https://foreverdb.net/class/Warrior/talents?lvl=60&t=62fd33.32005--250533120331121351",talents={[10]="Shield Specialization 1",[11]="Shield Specialization 2",[12]="Shield Specialization 3",[13]="Shield Specialization 4",[14]="Shield Specialization 5",[15]="Improved Revenge 1",[16]="Improved Revenge 2",[17]="Improved Revenge 3",[18]="Improved Bloodrage 1",[19]="Improved Bloodrage 2",[20]="Last Stand 1",[21]="Master of Defense 1",[22]="Master of Defense 2",[23]="Anticipation 1",[24]="Anticipation 2",[25]="Anticipation 3",[26]="Vanguard 1",[27]="Improved Sunder Armor 1",[28]="Improved Sunder Armor 2",[29]="Improved Sunder Armor 3",[30]="Concussion Blow 1",[31]="Focused Rage 1",[32]="Focused Rage 2",[33]="Focused Rage 3",[34]="Anticipation 4",[35]="Anticipation 5",[36]="Bastion 1",[37]="Bastion 2",[38]="Bastion 3",[39]="Bastion 4",[40]="Bastion 5",[41]="Shield Slam 1",[42]="Defiance 1",[43]="Defiance 2",[44]="Defiance 3",[45]="Improved Thunder Clap 1",[46]="Improved Thunder Clap 2",[47]="Improved Thunder Clap 3",[48]="Improved Shield Wall 1",[49]="Improved Shield Wall 2",[50]="Improved Shield Bash 1",[51]="Improved Heroic Strike 1",[52]="Improved Heroic Strike 2",[53]="Improved Heroic Strike 3",[54]="Deflection 1",[55]="Deflection 2",[56]="Improved Tactical Mastery 1",[57]="Improved Tactical Mastery 2",[58]="Improved Tactical Mastery 3",[59]="Improved Tactical Mastery 4",[60]="Improved Tactical Mastery 5"},notes={[10]="Shield Specialization: more blocks, and on Forever each block also gives rage.",[15]="Improved Revenge makes Revenge, which you can use after each block, a real damage hit.",[20]="Last Stand is your emergency cooldown when a pull goes wrong.",[26]="Vanguard lets you Charge from Defensive Stance: no stance dance to open a pull.",[30]="Concussion Blow is a stun on demand, for an interrupt or to reach a runner.",[36]="Bastion adds damage to everything you do with a shield on; it is what makes Protection level well.",[41]="Shield Slam is the capstone: a big hit that grows with your block value, and high threat for dungeons.",[42]="Defiance, Improved Thunder Clap and Improved Shield Wall round out the tank kit for dungeons.",[51]="The last 10 points go to Arms: cheaper Heroic Strikes and Improved Tactical Mastery for swaps to Battle Stance."}}}})
